class Solution {
    private String replace(String text,char from,char to){
        return text.replace(from,to);
    }
    public int maxDiff(int num){
        String text=String.valueOf(num),maximum=text,minimum=text;
        for(char value:text.toCharArray())if(value!='9'){
            maximum=replace(text,value,'9');
            break;
        }
        if(text.charAt(0)!='1')minimum=replace(text,text.charAt(0),'1');
        else for(int i=1;i<text.length();i++)if(text.charAt(i)!='0'&&text.charAt(i)!='1'){
            minimum=replace(text,text.charAt(i),'0');
            break;
        }
        return Integer.parseInt(maximum)-Integer.parseInt(minimum);
    }
}

code.kotlin:
class Solution {
    fun maxDiff(num:Int):Int{
        val text=num.toString();
        var maximum=text;
        var minimum=text;
        text.firstOrNull{
            it!='9'
        }?.let{
            maximum=text.replace(it,'9')
        };
        if(text[0]!='1')minimum=text.replace(text[0],'1')else text.drop(1).firstOrNull{
            it!='0'&&it!='1'
        }?.let{
            minimum=text.replace(it,'0')
        };
        return maximum.toInt()-minimum.toInt()
    }
}

